-- RLS benchmark at school scale (docs/PERFORMANCE.md). LOCAL ONLY.
--
-- Times the SQL the app's hot pages send, exactly as PostgREST sends it, as a
-- real user: `role authenticated` with request.jwt.claims, as PostgREST does
-- (and as the pgTAP helpers do). Each query: one warm-up run, then the median
-- of :runs `EXPLAIN (ANALYZE, TIMING OFF, BUFFERS)` runs (planning +
-- execution), plus its row count and an order-insensitive checksum of what it
-- returns, so a change to policies or indexes can be checked to return the
-- same rows for the same user.
--
-- The statements below were captured from PostgREST v16 (log_min_duration_statement
-- = 0) while scripts/perf/pages.perf.ts ran the real query functions of
-- src/server/queries/*.ts; ids and times are {placeholders} resolved below, so
-- the file works on any load of scripts/perf/seed-scale.sql. To refresh after
-- the app's queries change, see docs/PERFORMANCE.md, "Refreshing the queries".
--
-- Run: pnpm perf:bench  (scripts/perf/perf.mjs; or psql -f with the -v options below)
--   -v runs=7   -v now='2026-10-13 12:00:00+00'   -v plans=1
--   -v student=… -v teacher=… -v office=… -v manager=…   (emails)
-- Output: a CSV block after the line "-- bench:csv" (and plans after "-- bench:plans").

\set ON_ERROR_STOP 1
\set QUIET 1
\pset pager off

\if :{?runs} \else \set runs 7 \endif
\if :{?plans} \else \set plans 0 \endif
\if :{?student} \else \set student 'perf.student.8@example.com' \endif
\if :{?teacher} \else \set teacher 'perf.teacher.1@example.com' \endif
\if :{?office} \else \set office 'perf.office.1@example.com' \endif
\if :{?manager} \else \set manager 'manager@example.com' \endif
\if :{?admin} \else \set admin 'admin@example.com' \endif
\if :{?now} \else
  select now()::text as now \gset
\endif

-- ── who and what ────────────────────────────────────────────────────────────
-- The same choices as scripts/perf/pages.perf.ts.
create temp table bench_param (name text primary key, value text not null);
insert into bench_param values
  ('runs', :'runs'), ('plans', :'plans'),
  ('student_email', :'student'), ('teacher_email', :'teacher'),
  ('office_email', :'office'), ('manager_email', :'manager'), ('admin_email', :'admin'),
  ('now', :'now');
insert into bench_param
select 'now' || case when d > 0 then '+' else '' end || d || 'd', (:'now'::timestamptz + d * interval '1 day')::text
from unnest(array[-15, -8, -7, -1, 1, 2, 7]) d;
-- The office's "today" (a date, in the school's time zone) and two weeks on.
insert into bench_param
select 'today' || case when d > 0 then '+' || d || 'd' else '' end,
       ((:'now'::timestamptz at time zone 'Asia/Jerusalem')::date + d)::text
from unnest(array[0, 14]) d;

create function pg_temp.p(p_name text) returns text language sql stable as $$
  select value from bench_param where name = p_name
$$;
create function pg_temp.ids(p_ids uuid[]) returns text language sql immutable as $$
  select case when coalesce(cardinality(p_ids), 0) = 0 then '{00000000-0000-0000-0000-000000000000}'
              else '{' || array_to_string(p_ids, ',') || '}' end
$$;

-- Student: their first active group (by enrolment), its course, their latest
-- attempt and latest page there.
insert into bench_param select 's_id', id from auth.users where email = pg_temp.p('student_email');
insert into bench_param
select 's_group', e.group_id from public.enrollments e
where e.student_id = pg_temp.p('s_id')::uuid and e.status = 'active'
order by e.created_at, e.group_id limit 1;
insert into bench_param select 's_course', course_id from public.groups where id = pg_temp.p('s_group')::uuid;
insert into bench_param
select 's_activity', activity_id from public.attempts
where user_id = pg_temp.p('s_id')::uuid and course_id = pg_temp.p('s_course')::uuid
order by updated_at desc limit 1;
insert into bench_param
select 's_attempt', id from public.attempts
where user_id = pg_temp.p('s_id')::uuid and course_id = pg_temp.p('s_course')::uuid
order by updated_at desc limit 1;
insert into bench_param
select 's_item', id from public.activity_items
where activity_id = pg_temp.p('s_activity')::uuid order by position limit 1;
-- An exercise of the course they have not started (for "start an activity").
insert into bench_param
select 's_new_activity', a.id from public.activities a
where a.course_id = pg_temp.p('s_course')::uuid and a.status = 'published' and a.created_by is null
  and not exists (select 1 from public.attempts t where t.user_id = pg_temp.p('s_id')::uuid and t.activity_id = a.id)
order by a.id limit 1;
insert into bench_param
select 's_section', book_section_id from public.section_progress
where user_id = pg_temp.p('s_id')::uuid and course_id = pg_temp.p('s_course')::uuid
order by updated_at desc limit 1;

-- Teacher: their largest group, its first active student (by id), and the
-- exercise of the group's most recent past homework.
insert into bench_param select 't_id', id from auth.users where email = pg_temp.p('teacher_email');
insert into bench_param
select 't_group', gt.group_id from public.group_teachers gt
where gt.teacher_id = pg_temp.p('t_id')::uuid
order by (select count(*) from public.enrollments e where e.group_id = gt.group_id) desc, gt.group_id limit 1;
insert into bench_param select 't_course', course_id from public.groups where id = pg_temp.p('t_group')::uuid;
insert into bench_param
select 't_student', min(student_id::text) from public.enrollments
where group_id = pg_temp.p('t_group')::uuid and status = 'active';
insert into bench_param
select 't_group_students', pg_temp.ids(array_agg(student_id order by student_id))
from public.enrollments where group_id = pg_temp.p('t_group')::uuid;
insert into bench_param
select 't_activity', activity_id from public.assignments
where group_id = pg_temp.p('t_group')::uuid and activity_id is not null and due_at < pg_temp.p('now')::timestamptz
order by due_at desc limit 1;
insert into bench_param
select 't_items', pg_temp.ids(array_agg(id order by position))
from public.activity_items where activity_id = pg_temp.p('t_activity')::uuid;
-- Teacher's day: their groups, classes in the attendance window, homework due this week.
insert into bench_param
select 't_groups', pg_temp.ids(array_agg(group_id order by group_id))
from public.group_teachers where teacher_id = pg_temp.p('t_id')::uuid;
insert into bench_param
select 't_sessions', pg_temp.ids(array_agg(id order by starts_at))
from public.group_sessions
where group_id = any(pg_temp.p('t_groups')::uuid[])
  and starts_at >= pg_temp.p('now-15d')::timestamptz and starts_at <= pg_temp.p('now+2d')::timestamptz;
create temp table bench_due as
select a.* from public.assignments a
where a.group_id = any(pg_temp.p('t_groups')::uuid[])
  and a.due_at >= pg_temp.p('now')::timestamptz and a.due_at <= pg_temp.p('now+7d')::timestamptz
  and a.vocabulary_set_id is null;
insert into bench_param
select 't_due_activities', pg_temp.ids(array_agg(activity_id) filter (where activity_id is not null)) from bench_due;
insert into bench_param
select 't_due_sections', pg_temp.ids(array_agg(book_section_id) filter (where book_section_id is not null)) from bench_due;
insert into bench_param
select 't_due_students', pg_temp.ids(array_agg(distinct s)) from (
  select e.student_id as s from bench_due d join public.enrollments e on e.group_id = d.group_id and e.status = 'active'
  where d.audience = 'group'
  union
  select r.student_id from bench_due d join public.assignment_recipients r on r.assignment_id = d.id
  where d.audience = 'selected'
) x;
-- The group page: its six latest past classes.
insert into bench_param
select 't_past_sessions', pg_temp.ids(array_agg(id order by starts_at desc)) from (
  select id, starts_at from public.group_sessions
  where group_id = pg_temp.p('t_group')::uuid and starts_at < pg_temp.p('now')::timestamptz
  order by starts_at desc limit 6
) x;
-- The questions the group page shows as common difficulties: read through
-- the view as the teacher (it shows nothing to anyone else).
do $$
declare v text; v_group uuid := pg_temp.p('t_group')::uuid;
begin
  perform set_config('request.jwt.claims', json_build_object(
    'sub', pg_temp.p('t_id'), 'role', 'authenticated', 'aal', 'aal1')::text, true);
  perform set_config('role', 'authenticated', true);
  select coalesce('{' || string_agg(item_id::text, ',' order by wrong_rate desc, students desc, item_id) || '}',
                  '{00000000-0000-0000-0000-000000000000}') into v from (
    select item_id, wrong_rate, students from public.group_item_first_tries
    where group_id = v_group and students >= 3 and wrong_rate >= 0.5
    order by wrong_rate desc, students desc, item_id limit 5
  ) x;
  perform set_config('role', 'postgres', true);
  insert into bench_param values ('t_difficult_items', v);
end $$;
-- Office: the first page of the students list (50 by name).
insert into bench_param
select 'o_students', pg_temp.ids(array_agg(id order by display_name, id)) from (
  select p.id, p.display_name from public.profiles p
  where exists (select 1 from public.user_roles r where r.user_id = p.id and r.role = 'student')
  order by p.display_name, p.id limit 50
) x;

do $$
declare v text;
begin
  foreach v in array array['s_id','s_group','s_course','s_activity','s_attempt','s_item','s_section','s_new_activity',
                           't_id','t_group','t_course','t_student','t_activity'] loop
    if pg_temp.p(v) is null then
      raise exception 'bench parameter % is missing: is scripts/perf/seed-scale.sql loaded?', v;
    end if;
  end loop;
end $$;

-- ── the timer ───────────────────────────────────────────────────────────────
create temp table bench_result (
  n serial, who text, label text, median_ms numeric, min_ms numeric, max_ms numeric,
  total_rows bigint, page_rows bigint, checksum text, shared_hit bigint, shared_read bigint, plan text
);

create function pg_temp.as_user(p_who text) returns void language plpgsql as $$
declare v_email text := pg_temp.p(p_who || '_email'); v_id uuid;
begin
  if p_who = 'service' then
    perform set_config('request.jwt.claims', '{"role":"service_role"}', true);
    perform set_config('role', 'service_role', true);
    return;
  end if;
  select id into strict v_id from auth.users where email = v_email;
  perform set_config('request.jwt.claims', json_build_object(
    'sub', v_id, 'role', 'authenticated', 'email', v_email,
    'aal', case when p_who in ('office', 'manager', 'admin') then 'aal2' else 'aal1' end)::text, true);
  perform set_config('role', 'authenticated', true);
end;
$$;

create function pg_temp.fill(p_sql text) returns text language plpgsql stable as $$
declare v_sql text := p_sql; r record;
begin
  for r in select name, value from bench_param order by length(name) desc loop
    v_sql := replace(v_sql, '{' || r.name || '}', quote_literal(r.value));
  end loop;
  return v_sql;
end;
$$;

-- A read, as PostgREST runs it: the statement returns (total, page count, body).
create function pg_temp.bench(p_who text, p_label text, p_sql text) returns void language plpgsql as $$
declare
  v_sql text := pg_temp.fill(p_sql);
  v_runs int := pg_temp.p('runs')::int;
  v_plans boolean := pg_temp.p('plans') = '1';
  v_plan json; v_ms numeric[] := '{}'; v_total bigint; v_page bigint; v_body text;
  v_sum text; v_text text := ''; r record;
begin
  perform pg_temp.as_user(p_who);
  execute 'explain (analyze, timing off, format json) ' || v_sql into v_plan; -- warm-up
  for i in 1..v_runs loop
    execute 'explain (analyze, timing off, buffers, format json) ' || v_sql into v_plan;
    v_ms := v_ms || ((v_plan -> 0 ->> 'Planning Time')::numeric + (v_plan -> 0 ->> 'Execution Time')::numeric);
  end loop;
  execute format('select total_result_set, page_total, body::text from (%s) t', v_sql)
    into v_total, v_page, v_body;
  if v_plans then
    for r in execute 'explain (analyze, buffers) ' || v_sql loop
      v_text := v_text || r."QUERY PLAN" || E'\n';
    end loop;
  end if;
  perform set_config('role', 'postgres', true);
  if v_body like '[%' then
    select md5(coalesce(string_agg(e::text, chr(1) order by e::text), '')) into v_sum
    from json_array_elements(v_body::json) e;
  end if;
  select array_agg(x order by x) into v_ms from unnest(v_ms) x;
  insert into bench_result (who, label, median_ms, min_ms, max_ms, total_rows, page_rows, checksum,
                            shared_hit, shared_read, plan)
  values (p_who, p_label, round(v_ms[(v_runs + 1) / 2], 2), round(v_ms[1], 2), round(v_ms[v_runs], 2),
          v_total, v_page, v_sum,
          (v_plan -> 0 -> 'Plan' ->> 'Shared Hit Blocks')::bigint,
          (v_plan -> 0 -> 'Plan' ->> 'Shared Read Blocks')::bigint,
          nullif(v_text, ''));
end;
$$;

-- A write, rolled back every time (nothing is kept): median wall time of :runs.
create function pg_temp.bench_write(p_who text, p_label text, p_sql text) returns void language plpgsql as $$
declare
  v_sql text := pg_temp.fill(p_sql);
  v_runs int := pg_temp.p('runs')::int;
  v_ms numeric[] := '{}'; v_t timestamptz; v_elapsed numeric;
begin
  for i in 0..v_runs loop
    begin
      perform pg_temp.as_user(p_who);
      v_t := clock_timestamp();
      execute v_sql;
      v_elapsed := extract(epoch from clock_timestamp() - v_t) * 1000;
      raise exception using errcode = 'P0001', message = 'bench: roll back';
    exception when sqlstate 'P0001' then
      if i > 0 then v_ms := v_ms || v_elapsed; end if; -- run 0 warms up
    end;
  end loop;
  perform set_config('role', 'postgres', true);
  select array_agg(x order by x) into v_ms from unnest(v_ms) x;
  insert into bench_result (who, label, median_ms, min_ms, max_ms)
  values (p_who, p_label, round(v_ms[(v_runs + 1) / 2], 2), round(v_ms[1], 2), round(v_ms[v_runs], 2));
end;
$$;

-- ── reads: the hot pages (captured from PostgREST) ─────────────────────────
\o /dev/null
select pg_temp.bench('student', 'my courses (enrollments → group → course → level → language)', $q$WITH pgrst_source AS ( SELECT row_to_json("enrollments_group_1".*)::jsonb AS "group" FROM "public"."enrollments" LEFT JOIN LATERAL ( SELECT "groups_1"."id", "groups_1"."name", row_to_json("groups_course_2".*)::jsonb AS "course" FROM "public"."groups" AS "groups_1" LEFT JOIN LATERAL ( SELECT "courses_2"."id", "courses_2"."title", "courses_2"."pilot", row_to_json("courses_level_3".*)::jsonb AS "level" FROM "public"."courses" AS "courses_2" LEFT JOIN LATERAL ( SELECT "levels_3"."title", row_to_json("levels_language_4".*)::jsonb AS "language" FROM "public"."levels" AS "levels_3" LEFT JOIN LATERAL ( SELECT "languages_4"."name", "languages_4"."code", "languages_4"."direction" FROM "public"."languages" AS "languages_4" WHERE "languages_4"."id" = "levels_3"."language_id"   LIMIT '1000' OFFSET '0' ) AS "levels_language_4" ON TRUE WHERE "levels_3"."id" = "courses_2"."level_id"   LIMIT '1000' OFFSET '0' ) AS "courses_level_3" ON TRUE WHERE "courses_2"."id" = "groups_1"."course_id"   LIMIT '1000' OFFSET '0' ) AS "groups_course_2" ON TRUE WHERE "groups_1"."id" = "public"."enrollments"."group_id"   LIMIT '1000' OFFSET '0' ) AS "enrollments_group_1" ON TRUE WHERE  "public"."enrollments"."student_id" = {s_id} AND  "public"."enrollments"."status" = 'active'   LIMIT '1000' OFFSET '0' )  SELECT null::bigint AS total_result_set, pg_catalog.count(_postgrest_t) AS page_total, coalesce(json_agg(_postgrest_t), '[]') AS body, nullif(current_setting('response.headers', true), '') AS response_headers, nullif(current_setting('response.status', true), '') AS response_status, '' AS response_inserted FROM ( SELECT * FROM pgrst_source ) _postgrest_t$q$);

select pg_temp.bench('student', 'dashboard: recommendation feedback', $q$WITH pgrst_source AS ( SELECT "public"."recommendation_feedback"."rec_key" FROM "public"."recommendation_feedback" WHERE  "public"."recommendation_feedback"."user_id" = {s_id} AND  "public"."recommendation_feedback"."action" = 'dismissed' AND  "public"."recommendation_feedback"."at" >= {now-7d}   LIMIT '1000' OFFSET '0' )  SELECT null::bigint AS total_result_set, pg_catalog.count(_postgrest_t) AS page_total, coalesce(json_agg(_postgrest_t), '[]') AS body, nullif(current_setting('response.headers', true), '') AS response_headers, nullif(current_setting('response.status', true), '') AS response_status, '' AS response_inserted FROM ( SELECT * FROM pgrst_source ) _postgrest_t$q$);

select pg_temp.bench('student', 'dashboard: skills', $q$WITH pgrst_source AS ( SELECT "public"."skills"."id", "public"."skills"."label" FROM "public"."skills"   LIMIT '1000' OFFSET '0' )  SELECT null::bigint AS total_result_set, pg_catalog.count(_postgrest_t) AS page_total, coalesce(json_agg(_postgrest_t), '[]') AS body, nullif(current_setting('response.headers', true), '') AS response_headers, nullif(current_setting('response.status', true), '') AS response_status, '' AS response_inserted FROM ( SELECT * FROM pgrst_source ) _postgrest_t$q$);

select pg_temp.bench('student', 'dashboard: words due (count)', $q$WITH pgrst_source AS ( SELECT "public"."vocab_review_state"."vocabulary_item_id" FROM "public"."vocab_review_state" WHERE  "public"."vocab_review_state"."user_id" = {s_id} AND  "public"."vocab_review_state"."course_id" = {s_course} AND  "public"."vocab_review_state"."due_at" <= {now}   LIMIT '1000' OFFSET '0' ) , pgrst_source_count AS (SELECT 1  FROM "public"."vocab_review_state" WHERE  "public"."vocab_review_state"."user_id" = {s_id} AND  "public"."vocab_review_state"."course_id" = {s_course} AND  "public"."vocab_review_state"."due_at" <= {now}) SELECT (SELECT pg_catalog.count(*) FROM pgrst_source_count) AS total_result_set, pg_catalog.count(_postgrest_t) AS page_total, ''::text AS body, nullif(current_setting('response.headers', true), '') AS response_headers, nullif(current_setting('response.status', true), '') AS response_status, '' AS response_inserted FROM ( SELECT * FROM pgrst_source ) _postgrest_t$q$);

select pg_temp.bench('student', 'dashboard: next class', $q$WITH pgrst_source AS ( SELECT "public"."group_sessions"."starts_at" FROM "public"."group_sessions" WHERE  "public"."group_sessions"."group_id" = {s_group} AND  "public"."group_sessions"."starts_at" > {now}  ORDER BY "public"."group_sessions"."starts_at" ASC  LIMIT '1' OFFSET '0' )  SELECT null::bigint AS total_result_set, pg_catalog.count(_postgrest_t) AS page_total, coalesce(json_agg(_postgrest_t), '[]') AS body, nullif(current_setting('response.headers', true), '') AS response_headers, nullif(current_setting('response.status', true), '') AS response_status, '' AS response_inserted FROM ( SELECT * FROM pgrst_source ) _postgrest_t$q$);

select pg_temp.bench('student', 'dashboard: finished sections', $q$WITH pgrst_source AS ( SELECT "public"."section_progress"."book_section_id" FROM "public"."section_progress" WHERE  "public"."section_progress"."user_id" = {s_id} AND  "public"."section_progress"."course_id" = {s_course} AND  "public"."section_progress"."status" = 'completed'   LIMIT '1000' OFFSET '0' )  SELECT null::bigint AS total_result_set, pg_catalog.count(_postgrest_t) AS page_total, coalesce(json_agg(_postgrest_t), '[]') AS body, nullif(current_setting('response.headers', true), '') AS response_headers, nullif(current_setting('response.status', true), '') AS response_status, '' AS response_inserted FROM ( SELECT * FROM pgrst_source ) _postgrest_t$q$);

select pg_temp.bench('student', 'dashboard: active cycles', $q$WITH pgrst_source AS ( SELECT "public"."group_cycles"."cycle_id", row_to_json("group_cycles_cycle_1".*)::jsonb AS "cycle" FROM "public"."group_cycles" LEFT JOIN LATERAL ( SELECT "cycles_1"."title" FROM "public"."cycles" AS "cycles_1" WHERE "cycles_1"."id" = "public"."group_cycles"."cycle_id" AND "cycles_1"."course_id" = "public"."group_cycles"."course_id"   LIMIT '1000' OFFSET '0' ) AS "group_cycles_cycle_1" ON TRUE WHERE  "public"."group_cycles"."group_id" = {s_group} AND  "public"."group_cycles"."state" = 'active'  ORDER BY "public"."group_cycles"."position" ASC  LIMIT '1000' OFFSET '0' )  SELECT null::bigint AS total_result_set, pg_catalog.count(_postgrest_t) AS page_total, coalesce(json_agg(_postgrest_t), '[]') AS body, nullif(current_setting('response.headers', true), '') AS response_headers, nullif(current_setting('response.status', true), '') AS response_status, '' AS response_inserted FROM ( SELECT * FROM pgrst_source ) _postgrest_t$q$);

