ections_book_2".*)::jsonb AS "book" FROM "public"."book_sections" AS "book_sections_1" LEFT JOIN LATERAL ( SELECT "books_2"."kind" FROM "public"."books" AS "books_2" WHERE "books_2"."id" = "book_sections_1"."book_id" AND "books_2"."course_id" = "book_sections_1"."course_id"   LIMIT '1000' OFFSET '0' ) AS "book_sections_book_2" ON TRUE WHERE "book_sections_1"."id" = "public"."content_reports"."book_section_id" AND "book_sections_1"."course_id" = "public"."content_reports"."course_id"   LIMIT '1000' OFFSET '0' ) AS "content_reports_section_1" ON TRUE  LEFT JOIN LATERAL ( SELECT "profiles_1"."display_name" FROM "public"."profiles" AS "profiles_1" WHERE "profiles_1"."id" = "public"."content_reports"."reporter_id"   LIMIT '1000' OFFSET '0' ) AS "content_reports_reporter_1" ON TRUE  LEFT JOIN LATERAL ( SELECT "profiles_1"."display_name" FROM "public"."profiles" AS "profiles_1" WHERE "profiles_1"."id" = "public"."content_reports"."resolved_by"   LIMIT '1000' OFFSET '0' ) AS "content_reports_resolver_1" ON TRUE  LEFT JOIN LATERAL ( SELECT json_agg("content_reports_corrections_1")::jsonb AS "content_reports_corrections_1" FROM (SELECT "item_corrections_1"."corrected_at", "item_corrections_1"."reason" FROM "public"."item_corrections" AS "item_corrections_1" WHERE "item_corrections_1"."report_id" = "public"."content_reports"."id"   LIMIT '1000' OFFSET '0' ) AS "content_reports_corrections_1" ) AS "content_reports_corrections_1" ON TRUE  ORDER BY "public"."content_reports"."created_at" DESC , "public"."content_reports"."id" ASC  LIMIT '500' OFFSET '0' ) , pgrst_source_count AS (SELECT 1  FROM "public"."content_reports") SELECT (SELECT pg_catalog.count(*) FROM pgrst_source_count) AS total_result_set, pg_catalog.count(_postgrest_t) AS page_total, coalesce(json_agg(_postgrest_t), '[]') AS body, nullif(current_setting('response.headers', true), '') AS response_headers, nullif(current_setting('response.status', true), '') AS response_status, '' AS response_inserted FROM ( SELECT * FROM pgrst_source ) _postgrest_t$q$);

