sections_book_2".*)::jsonb AS "book" FROM "public"."book_sections" AS "book_sections_1" LEFT JOIN LATERAL ( SELECT "books_2"."kind" FROM "public"."books" AS "books_2" WHERE "books_2"."id" = "book_sections_1"."book_id" AND "books_2"."course_id" = "book_sections_1"."course_id"   LIMIT '1000' OFFSET '0' ) AS "book_sections_book_2" ON TRUE WHERE "book_sections_1"."id" = "public"."content_reports"."book_section_id" AND "book_sections_1"."course_id" = "public"."content_reports"."course_id"   LIMIT '1000' OFFSET '0' ) AS "content_reports_section_1" ON TRUE  LEFT JOIN LATERAL ( SELECT "profiles_1"."display_name" FROM "public"."profiles" AS "profiles_1" WHERE "profiles_1"."id" = "public"."content_reports"."reporter_id"   LIMIT '1000' OFFSET '0' ) AS "content_reports_reporter_1" ON TRUE  LEFT JOIN LATERAL ( SELECT "profiles_1"."display_name" FROM "public"."profiles" AS "profiles_1" WHERE "profiles_1"."id" = "public"."content_reports"."resolved_by"   LIMIT '1000' OFFSET '0' ) AS "content_reports_resolver_1" ON TRUE  LEFT JOIN LATERAL ( SELECT json_agg("content_reports_corrections_1")::jsonb AS "content_reports_corrections_1" FROM (SELECT "item_corrections_1"."corrected_at", "item_corrections_1"."reason" FROM "public"."item_corrections" AS "item_corrections_1" WHERE "item_corrections_1"."report_id" = "public"."content_reports"."id"   LIMIT '1000' OFFSET '0' ) AS "content_reports_corrections_1" ) AS "content_reports_corrections_1" ON TRUE WHERE  "public"."content_reports"."status" = 'open'  ORDER BY "public"."content_reports"."created_at" DESC , "public"."content_reports"."id" ASC  LIMIT '500' OFFSET '0' ) , pgrst_source_count AS (SELECT 1  FROM "public"."content_reports" WHERE  "public"."content_reports"."status" = 'open') SELECT (SELECT pg_catalog.count(*) FROM pgrst_source_count) AS total_result_set, pg_catalog.count(_postgrest_t) AS page_total, coalesce(json_agg(_postgrest_t), '[]') AS body, nullif(current_setting('response.headers', true), '') AS response_headers, nullif(current_setting('response.status', true), '') AS response_status, '' AS response_inserted FROM ( SELECT * FROM pgrst_source ) _postgrest_t$q$);

select pg_temp.bench('manager', 'groups (all pages)', $q$WITH pgrst_source AS ( SELECT "public"."groups"."id", "public"."groups"."name", "public"."groups"."status", row_to_json("groups_course_1".*)::jsonb AS "course", COALESCE( "groups_group_teachers_1"."groups_group_teachers_1", '[]') AS "group_teachers", COALESCE( "groups_enrollments_1"."groups_enrollments_1", '[]') AS "enrollments" FROM "public"."groups" LEFT JOIN LATERAL ( SELECT "courses_1"."title" FROM "public"."courses" AS "courses_1" WHERE "courses_1"."id" = "public"."groups"."course_id"   LIMIT '1000' OFFSET '0' ) AS "groups_course_1" ON TRUE  LEFT JOIN LATERAL ( SELECT json_agg("groups_group_teachers_1")::jsonb AS "groups_group_teachers_1" FROM (SELECT row_to_json("group_teachers_teacher_2".*)::jsonb AS "teacher" FROM "public"."group_teachers" AS "group_teachers_1" LEFT JOIN LATERAL ( SELECT "profiles_2"."display_name" FROM "public"."profiles" AS "profiles_2" WHERE "profiles_2"."id" = "group_teachers_1"."teacher_id"   LIMIT '1000' OFFSET '0' ) AS "group_teachers_teacher_2" ON TRUE WHERE "group_teachers_1"."group_id" = "public"."groups"."id"   LIMIT '1000' OFFSET '0' ) AS "groups_group_teachers_1" ) AS "groups_group_teachers_1" ON TRUE  LEFT JOIN LATERAL ( SELECT json_agg("groups_enrollments_1")::jsonb AS "groups_enrollments_1" FROM (SELECT "enrollments_1"."status" FROM "public"."enrollments" AS "enrollments_1" WHERE "enrollments_1"."group_id" = "public"."groups"."id"   LIMIT '1000' OFFSET '0' ) AS "groups_enrollments_1" ) AS "groups_enrollments_1" ON TRUE  ORDER BY "public"."groups"."name" ASC , "public"."groups"."id" ASC  LIMIT '1000' OFFSET '0' )  SELECT null::bigint AS total_result_set, pg_catalog.count(_postgrest_t) AS page_total, coalesce(json_agg(_postgrest_t), '[]') AS body, nullif(current_setting('response.headers', true), '') AS response_headers, nullif(current_setting('response.status', true), '') AS response_status, '' AS response_inserted FROM ( SELECT * FROM pgrst_source ) _postgrest_t$q$);

select pg_temp.bench('admin', 'accounts: page 1 (50, with total)', $q$WITH pgrst_source AS ( SELECT "public"."profiles"."id", "public"."profiles"."display_name", "public"."profiles"."created_at", COALESCE( "profiles_user_roles_1"."profiles_user_roles_1", '[]') AS "user_roles" FROM "public"."profiles" LEFT JOIN LATERAL ( SELECT json_agg("profiles_user_roles_1")::jsonb AS "profiles_user_roles_1" FROM (SELECT "user_roles_1"."role" FROM "public"."user_roles" AS "user_roles_1" WHERE "user_roles_1"."user_id" = "public"."profiles"."id"   LIMIT '1000' OFFSET '0' ) AS "profiles_user_roles_1" ) AS "profiles_user_roles_1" ON TRUE  ORDER BY "public"."profiles"."display_name" ASC , "public"."profiles"."id" ASC  LIMIT '50' OFFSET '0' ) , pgrst_source_count AS (SELECT 1  FROM "public"."profiles") SELECT (SELECT pg_catalog.count(*) FROM pgrst_source_count) AS total_result_set, pg_catalog.count(_postgrest_t) AS page_total, coalesce(json_agg(_postgrest_t), '[]') AS body, nullif(current_setting('response.headers', true), '') AS response_headers, nullif(current_setting('response.status', true), '') AS response_status, '' AS response_inserted FROM ( SELECT * FROM pgrst_source ) _postgrest_t$q$);

select pg_temp.bench('admin', 'accounts: search by name', $q$WITH pgrst_source AS ( SELECT "public"."profiles"."id", "public"."profiles"."display_name", "public"."profiles"."created_at", COALESCE( "profiles_user_roles_1"."profiles_user_roles_1", '[]') AS "user_roles" FROM "public"."profiles" LEFT JOIN LATERAL ( SELECT json_agg("profiles_user_roles_1")::jsonb AS "profiles_user_roles_1" FROM (SELECT "user_roles_1"."role" FROM "public"."user_roles" AS "user_roles_1" WHERE "user_roles_1"."user_id" = "public"."profiles"."id"   LIMIT '1000' OFFSET '0' ) AS "profiles_user_roles_1" ) AS "profiles_user_roles_1" ON TRUE WHERE  "public"."profiles"."display_name" ilike '%teacher%'  ORDER BY "public"."profiles"."display_name" ASC , "public"."profiles"."id" ASC  LIMIT '50' OFFSET '0' ) , pgrst_source_count AS (SELECT 1  FROM "public"."profiles" WHERE  "public"."profiles"."display_name" ilike '%teacher%') SELECT (SELECT pg_catalog.count(*) FROM pgrst_source_count) AS total_result_set, pg_catalog.count(_postgrest_t) AS page_total, coalesce(json_agg(_postgrest_t), '[]') AS body, nullif(current_setting('response.headers', true), '') AS response_headers, nullif(current_setting('response.status', true), '') AS response_status, '' AS response_inserted FROM ( SELECT * FROM pgrst_source ) _postgrest_t$q$);

-- ── writes: answering an exercise (src/server/actions/attempts.ts) ─────────
-- The reads checkAnswer and startActivity make with the student's session,
-- in PostgREST's shape, then the writes the server makes with the secret key
-- (service_role), each rolled back.
select pg_temp.bench('student', 'answer: my open attempt', $q$WITH pgrst_source AS ( SELECT "public"."attempts"."id", "public"."attempts"."activity_id", "public"."attempts"."course_id", "public"."attempts"."assignment_id", "public"."attempts"."status", "public"."attempts"."state" FROM "public"."attempts" WHERE  "public"."attempts"."id" = {s_attempt} AND  "public"."attempts"."user_id" = {s_id}   LIMIT '1000' OFFSET '0' )  SELECT null::bigint AS total_result_set, pg_catalog.count(_postgrest_t) AS page_total, coalesce(json_agg(_postgrest_t), '[]') AS body, nullif(current_setting('response.headers', true), '') AS response_headers, nullif(current_setting('response.status', true), '') AS response_status, '' AS response_inserted FROM ( SELECT * FROM pgrst_source ) _postgrest_t$q$);

select pg_temp.bench('service', 'answer: rate limit (answers in the last minute)', $q$WITH pgrst_source AS ( SELECT "public"."responses"."id" FROM "public"."responses" WHERE  "public"."responses"."user_id" = {s_id} AND  "public"."responses"."created_at" >= ({now}::timestamptz - interval '1 minute')   LIMIT '1000' OFFSET '0' ) , pgrst_source_count AS (SELECT 1  FROM "public"."responses" WHERE  "public"."responses"."user_id" = {s_id} AND  "public"."responses"."created_at" >= ({now}::timestamptz - interval '1 minute')) SELECT (SELECT pg_catalog.count(*) FROM pgrst_source_count) AS total_result_set, pg_catalog.count(_postgrest_t) AS page_total, ''::text AS body, nullif(current_setting('response.headers', true), '') AS response_headers, nullif(current_setting('response.status', true), '') AS response_status, '' AS response_inserted FROM ( SELECT * FROM pgrst_source ) _postgrest_t$q$);

select pg_temp.bench('service', 'answer: answer key', $q$WITH pgrst_source AS ( SELECT "public"."activity_item_keys"."answer", "public"."activity_item_keys"."feedback" FROM "public"."activity_item_keys" WHERE  "public"."activity_item_keys"."item_id" = {s_item}   LIMIT '1000' OFFSET '0' )  SELECT null::bigint AS total_result_set, pg_catalog.count(_postgrest_t) AS page_total, coalesce(json_agg(_postgrest_t), '[]') AS body, nullif(current_setting('response.headers', true), '') AS response_headers, nullif(current_setting('response.status', true), '') AS response_status, '' AS response_inserted FROM ( SELECT * FROM pgrst_source ) _postgrest_t$q$);

select pg_temp.bench_write('service', 'answer: insert response + update attempt state', $q$
  insert into public.responses (attempt_id, user_id, course_id, item_id, answer, is_correct, score, feedback_code, try_no)
  values ({s_attempt}, {s_id}, {s_course}, {s_item}, '{"optionIds": ["o1"]}', false, 0, 'chose:o1', 9);
  update public.attempts set state = jsonb_set(state, '{bench}', 'true') where id = {s_attempt} and user_id = {s_id};
$q$);

select pg_temp.bench('student', 'start: my attempts at the activity', $q$WITH pgrst_source AS ( SELECT "public"."attempts"."id", "public"."attempts"."status", "public"."attempts"."attempt_no" FROM "public"."attempts" WHERE  "public"."attempts"."user_id" = {s_id} AND  "public"."attempts"."activity_id" = {s_new_activity}   LIMIT '1000' OFFSET '0' )  SELECT null::bigint AS total_result_set, pg_catalog.count(_postgrest_t) AS page_total, coalesce(json_agg(_postgrest_t), '[]') AS body, nullif(current_setting('response.headers', true), '') AS response_headers, nullif(current_setting('response.status', true), '') AS response_status, '' AS response_inserted FROM ( SELECT * FROM pgrst_source ) _postgrest_t$q$);

select pg_temp.bench('student', 'start: homework for the activity', $q$WITH pgrst_source AS ( SELECT "public"."assignments"."id" FROM "public"."assignments" WHERE  "public"."assignments"."activity_id" = {s_activity}  ORDER BY "public"."assignments"."created_at" DESC  LIMIT '1' OFFSET '0' )  SELECT null::bigint AS total_result_set, pg_catalog.count(_postgrest_t) AS page_total, coalesce(json_agg(_postgrest_t), '[]') AS body, nullif(current_setting('response.headers', true), '') AS response_headers, nullif(current_setting('response.status', true), '') AS response_status, '' AS response_inserted FROM ( SELECT * FROM pgrst_source ) _postgrest_t$q$);

select pg_temp.bench_write('service', 'start: insert attempt + learning event', $q$
  insert into public.attempts (user_id, activity_id, course_id, attempt_no)
  values ({s_id}, {s_new_activity}, {s_course}, 1);
  insert into public.learning_events (user_id, type, course_id, activity_id)
  values ({s_id}, 'activity_started', {s_course}, {s_new_activity});
$q$);

\o
-- ── results ─────────────────────────────────────────────────────────────────
\pset format aligned
select n, who, label, median_ms, min_ms, max_ms, coalesce(total_rows, page_rows) as rows, shared_hit, shared_read,
       case when median_ms >= 50 then 'SLOW' else '' end as flag
from bench_result order by n;

\echo '-- bench:csv'
\pset format csv
\pset tuples_only off
select who, label, median_ms, min_ms, max_ms, total_rows, page_rows, checksum, shared_hit, shared_read
from bench_result order by n;

\if :plans
\echo '-- bench:plans'
\pset format unaligned
\pset tuples_only on
select '### ' || who || ' · ' || label || E'\n' || plan from bench_result where plan is not null order by n;
\endif
